    ('act32side/level_act32side_02_beg_nep0num.csv', 'line-361', 'Может быть, нам стоит доложить Айле, будет мудрее действовать вчетвером.', 'Может быть, нам стоит доложить Эле, будет мудрее действовать вчетвером.'),
